rewrite:
def highest_base_score(vulns: List[Dict[str, Any]]) ->float:
    if not vulns:
        return 10.0

    scores = []
    for vuln in vulns:
        severity = vuln.get('severity', {})
        if severity:
            cvssv3 = severity.get('cvssv3', {})
            if cvssv3:
                base_score = cvssv3.get('base_score')
                if base_score is not None:
                    scores.append(base_score)

    if not scores:
        return 10.0

    return max(scores)
